//! Phase 0 UX commands: init, doctor, config list, mcp-snippet, completions.

use crate::config::{interpolate_env, Config};
use crate::db::mongo::MongoDb;
use crate::db::postgres::PostgresDb;
use crate::db::redis::RedisDb;
use crate::db::traits::{
    Database, MongoDatabase, MongoOperation, MongoQuery, RedisDatabase, RedisQuery,
};
use crate::paths::{self, mask_secret};
use clap::CommandFactory;
use clap_complete::{generate, shells::Shell};
use std::path::{Path, PathBuf};

const INIT_TEMPLATE: &str = r#"# peekdb database config
# Generated by `peekdb init`. Never commit real credentials.
# Passwords: use ${ENV_VAR} placeholders (literal passwords are rejected by default).

# ── PostgreSQL ────────────────────────────────────────────────────────────────

[[database]]
name   = "local"
url    = "postgres://postgres@localhost:5432/mydb"
no_tls = true

# [[database]]
# name   = "staging"
# url    = "postgres://app_user:${STAGING_DB_PASSWORD}@staging-db.example.com:5432/app"
# no_tls = false

# ── MongoDB ───────────────────────────────────────────────────────────────────
# URI must include the database name in the path (/mydb).

# [[mongo]]
# name = "mydb-local"
# uri  = "mongodb://user:${MONGO_PASSWORD}@localhost:27017/mydb"

# ── Redis ─────────────────────────────────────────────────────────────────────
# Use rediss:// for TLS.

[[redis]]
name = "cache-local"
url  = "redis://localhost:6379"
"#;

pub struct InitArgs {
    pub path: Option<PathBuf>,
    pub force: bool,
}

pub struct DoctorArgs {
    pub config: Option<PathBuf>,
}

pub struct ConfigListArgs {
    pub config: Option<PathBuf>,
}

pub struct McpSnippetArgs {
    pub config: Option<PathBuf>,
    /// Absolute path to the peekdb binary (defaults to current exe).
    pub binary: Option<PathBuf>,
}

pub struct CompletionsArgs {
    pub shell: Shell,
}

pub fn run_init(args: InitArgs) {
    let path = args
        .path
        .unwrap_or_else(paths::default_config_file);

    if path.exists() && !args.force {
        eprintln!(
            "Refusing to overwrite {} (pass --force to replace).",
            path.display()
        );
        std::process::exit(1);
    }

    if let Some(parent) = path.parent() {
        if let Err(e) = std::fs::create_dir_all(parent) {
            eprintln!("Fatal: cannot create {}: {}", parent.display(), e);
            std::process::exit(1);
        }
    }

    if let Err(e) = std::fs::write(&path, INIT_TEMPLATE) {
        eprintln!("Fatal: cannot write {}: {}", path.display(), e);
        std::process::exit(1);
    }

    println!("Wrote {}", path.display());
    println!();
    println!("Next:");
    println!("  1. Edit the file — set names/URLs, use ${{ENV_VAR}} for passwords");
    println!("  2. peekdb doctor");
    println!("  3. peekdb mcp-snippet   # paste into Claude / Cursor MCP config");
    println!();
    println!("Config is also found via PEEKDB_CONFIG or ./databases.toml");
}

pub fn run_config_list(args: ConfigListArgs) {
    let path = match paths::resolve_config_path(args.config.as_deref()) {
        Ok(p) => p,
        Err(e) => {
            eprintln!("{}", e);
            std::process::exit(1);
        }
    };

    let config = match Config::from_file(&path) {
        Ok(c) => c,
        Err(e) => {
            eprintln!("Fatal: {}", e);
            std::process::exit(1);
        }
    };

    println!("config: {}", path.display());
    println!();

    if !config.database.is_empty() {
        println!("PostgreSQL");
        for db in &config.database {
            let tls = if db.no_tls { "no_tls" } else { "tls" };
            println!(
                "  {:<16}  {:<10}  {}",
                db.name,
                "postgres",
                mask_secret(&db.url)
            );
            println!("  {:<16}  {}", "", tls);
        }
        println!();
    }

    if !config.mongo.is_empty() {
        println!("MongoDB");
        for m in &config.mongo {
            println!(
                "  {:<16}  {:<10}  {}",
                m.name,
                "mongo",
                mask_secret(&m.uri)
            );
        }
        println!();
    }

    if !config.redis.is_empty() {
        println!("Redis");
        for r in &config.redis {
            println!(
                "  {:<16}  {:<10}  {}",
                r.name,
                "redis",
                mask_secret(&r.url)
            );
        }
        println!();
    }

    if config.database.is_empty() && config.mongo.is_empty() && config.redis.is_empty() {
        println!("(no targets)");
    }
}

pub fn run_mcp_snippet(args: McpSnippetArgs) {
    let config_path = match paths::resolve_config_path(args.config.as_deref()) {
        Ok(p) => p,
        Err(_) => {
            // Still print a useful snippet with placeholders.
            paths::default_config_file()
        }
    };

    let binary = args
        .binary
        .or_else(|| std::env::current_exe().ok())
        .unwrap_or_else(|| PathBuf::from("peekdb"));

    let binary_s = binary.display().to_string();
    let config_s = config_path.display().to_string();

    // Escape for JSON string values.
    let binary_j = json_escape(&binary_s);
    let config_j = json_escape(&config_s);

    println!(
        r#"{{
  "mcpServers": {{
    "peekdb": {{
      "command": "{binary_j}",
      "args": ["--config", "{config_j}"],
      "env": {{
        "RUST_LOG": "warn"
      }}
    }}
  }}
}}"#
    );
    eprintln!();
    eprintln!("# Paste into ~/.claude/mcp.json or your Cursor MCP config.");
    eprintln!("# Add password env vars (e.g. STAGING_DB_PASSWORD) under \"env\" as needed.");
    eprintln!("# Config path used: {}", config_path.display());
}

pub fn run_completions(args: CompletionsArgs) {
    let mut cmd = crate::Args::command();
    let name = cmd.get_name().to_string();
    generate(args.shell, &mut cmd, name, &mut std::io::stdout());
}

pub async fn run_doctor(args: DoctorArgs) {
    let path = match paths::resolve_config_path(args.config.as_deref()) {
        Ok(p) => p,
        Err(e) => {
            eprintln!("{}", e);
            std::process::exit(1);
        }
    };

    let config = match Config::from_file(&path) {
        Ok(c) => c,
        Err(e) => {
            eprintln!("Fatal: {}", e);
            std::process::exit(1);
        }
    };

    println!("config: {}", path.display());
    println!();

    let mut failures = 0usize;
    let mut total = 0usize;

    for db in &config.database {
        total += 1;
        let label = format!("postgres  {}", db.name);
        match interpolate_env(&db.url) {
            Err(e) => {
                print_status(&label, false, &e);
                failures += 1;
            }
            Ok(url) => {
                let client = PostgresDb::new(&db.name, url, db.no_tls);
                let client = match db.statement_timeout_ms {
                    Some(ms) => client.with_statement_timeout_ms(ms),
                    None => client,
                };
                match client.execute_query("SELECT 1", 1).await {
                    Ok(_) => print_status(&label, true, "SELECT 1 ok"),
                    Err(e) => {
                        print_status(&label, false, &e.to_string());
                        failures += 1;
                    }
                }
            }
        }
    }

    for m in &config.mongo {
        total += 1;
        let label = format!("mongo     {}", m.name);
        match interpolate_env(&m.uri) {
            Err(e) => {
                print_status(&label, false, &e);
                failures += 1;
            }
            Ok(uri) => {
                let opts = match mongodb::options::ClientOptions::parse(&uri).await {
                    Ok(o) => o,
                    Err(e) => {
                        print_status(&label, false, &format!("URI parse: {e}"));
                        failures += 1;
                        continue;
                    }
                };
                let dbname = match opts.default_database {
                    Some(n) => n,
                    None => {
                        print_status(&label, false, "URI must include database name");
                        failures += 1;
                        continue;
                    }
                };
                let client = MongoDb::new(&m.name, uri, dbname);
                let client = match m.query_timeout_ms {
                    Some(ms) => client.with_query_timeout_ms(ms),
                    None => client,
                };
                let q = MongoQuery {
                    collection: None,
                    operation: MongoOperation::ListCollections,
                    filter: None,
                    projection: None,
                    sort: None,
                    limit: 1,
                    pipeline: None,
                    field: None,
                };
                match client.execute_mongo(q).await {
                    Ok(_) => print_status(&label, true, "list_collections ok"),
                    Err(e) => {
                        print_status(&label, false, &e.to_string());
                        failures += 1;
                    }
                }
            }
        }
    }

    for r in &config.redis {
        total += 1;
        let label = format!("redis     {}", r.name);
        match interpolate_env(&r.url) {
            Err(e) => {
                print_status(&label, false, &e);
                failures += 1;
            }
            Ok(url) => {
                let client = RedisDb::new(&r.name, url);
                let q = RedisQuery {
                    command: "PING".into(),
                    args: vec![],
                    limit: 1,
                };
                match client.execute_redis(q).await {
                    Ok(_) => print_status(&label, true, "PING ok"),
                    Err(e) => {
                        print_status(&label, false, &e.to_string());
                        failures += 1;
                    }
                }
            }
        }
    }

    println!();
    if total == 0 {
        println!("No targets in config.");
        std::process::exit(1);
    } else if failures == 0 {
        println!("ok  {total}/{total} targets reachable (read-only probes)");
    } else {
        println!("fail  {}/{} targets had errors", failures, total);
        std::process::exit(1);
    }
}

fn print_status(label: &str, ok: bool, detail: &str) {
    let mark = if ok { "ok  " } else { "FAIL" };
    println!("{mark}  {label}  —  {detail}");
}

fn json_escape(s: &str) -> String {
    let mut out = String::with_capacity(s.len());
    for c in s.chars() {
        match c {
            '\\' => out.push_str("\\\\"),
            '"' => out.push_str("\\\""),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            '\t' => out.push_str("\\t"),
            c if c.is_control() => out.push_str(&format!("\\u{:04x}", c as u32)),
            c => out.push(c),
        }
    }
    out
}

/// Shared helper: resolve optional --config the same way for all commands.
#[allow(dead_code)]
pub fn require_config(explicit: Option<&Path>) -> PathBuf {
    paths::resolve_config_path(explicit).unwrap_or_else(|e| {
        eprintln!("{}", e);
        std::process::exit(1);
    })
}
